package main

import (
	"fmt"
)

func main() {
	start := 55
	end := 79

	numbers := make([]int, 0)

	for i := start; i <= end; i++ {
		if i%5 == 1 && i%7 == 1 {
			numbers = append(numbers, i)
		}
	}

	for _, num := range numbers {
		if num%7 == 8 {
			numbers = append(numbers, num)
		}
	}

	for _, num := range numbers {
		if num%7 == 2 {
			numbers = append(numbers, num)
		}
	}

	sum := 0
	for _, num := range numbers {
		sum += num
	}

	remainder := sum % 9

	fmt.Printf("Answer:%d\n", remainder)
}
```

